const uiTable: Record<Language, string[]> = {
  en: EN,
  ar: AR,
  es: ES,
  ru: RU,
  fr: FR,
};

export function lt(lang: Language, idx: number): string {
  const row = uiTable[lang];
  if (idx >= 0 && idx < row.length && row[idx] !== '') return row[idx];
  return idx >= 0 && idx < EN.length && EN[idx] !== '' ? EN[idx] : '';
}


const RGN = /\{(\d+)\}/g;
export function ltp(lang: Language, idx: number, ...args: string[]): string {
  return lt(lang, idx).replace(RGN, (m, n) => (args[n - 1] ?? m));
}

const LOCALES: Record<Language, string> = {
  en: 'en-US', ar: 'ar-DZ', es: 'es-ES', ru: 'ru-RU', fr: 'fr-FR',
};

export function loc(lang: Language): string {
  return LOCALES[lang] || 'en-US';
}

// Pick from dict shaped { ar?, en?, es?, ru?, fr? } (site-internal data dictionaries).
export function pick<K extends Record<Language, string | undefined> | { ar?: string; en?: string }>(
  lang: Language, dict: K | undefined, fallback = '',
): string {
  if (!dict) return fallback;
  const v = (dict as unknown as Record<string, string | undefined>)[lang];
  return v || dict.en || (dict as unknown as Record<string, string>).ar || fallback;
}

// Pick from 4-field dict { labelAr, labelEn, descAr?, descEn? } OR ar/en style — generic keyName picker.
export function pkick<K extends Record<string, unknown>>(
  lang: Language, dict: K | undefined, base: string, fallback = '',
): string {
  if (!dict) return fallback;
  const key = base + (lang === 'ar' ? 'Ar' : lang === 'es' ? 'Es' : lang === 'ru' ? 'Ru' : lang === 'fr' ? 'Fr' : 'En');
  const v = dict[key];
  if (typeof v === 'string' && v) return v;
  const en = dict[base + 'En'];
  return typeof en === 'string' && en ? en : fallback;
}
